const script = `
$ProgressPreference='SilentlyContinue'
$h=@{'User-Agent'='dsh-check';'Accept'='application/vnd.github+json'}
$queries = @(
 'dsh plugin free model',
 'topic:dsh-plugin free',
 'topic:dsh-plugin model',
 'dsh-plugin api key free',
 'topic:free-model',
 'dsh plugin 免费',
 'dsh plugin gateway',
 'dsh plugin proxy'
)
foreach ($q in $queries) {
  "##### QUERY: $q"
  $enc = [uri]::EscapeDataString($q)
  try {
    $r = Invoke-RestMethod -Uri "https://api.github.com/search/repositories?q=$enc&sort=stars&order=desc&per_page=15" -Headers $h -TimeoutSec 40
    foreach ($i in $r.items) { "$($i.stargazers_count)|$($i.full_name)|$($i.description)" }
  } catch { "ERR: $($_.Exception.Message)" }
  Start-Sleep -Milliseconds 400
}
`;
const r = await tools.pwsh({ command: script, description: "Search GitHub for free-model plugin alternatives", timeoutMs: 180000 });
console.log(r.kind === "foreground" ? (r.stdout.text + r.stderr.text).slice(0, 9000) : JSON.stringify(r).slice(0,500));
